calc.mjs.text:
// Pure fee/payout arithmetic for a Discogs Marketplace sale. No network, no
// live schedule beyond the constants below.
//
// What Discogs publishes (Discogs Help Center, "What Are The Fees For Selling
// On Discogs?", and the 2023 "Selling Fee FAQ"): a 9% selling fee, charged on
// the item price PLUS the shipping the buyer pays, with a minimum of $0.10 and
// a maximum of $150 per order. Listing is free. The 9% took effect on
// May 22, 2023 (it was 8% before).
//
// What Discogs does not publish as one number: the payment processing fee the
// seller's payment provider takes on the same order. It differs by country and
// by account, and the figures quoted by third parties disagree (2.7% + $0.25,
// 2.9% + $0.30, 3.49% + $0.49). So the processing rate and fixed amount are
// two inputs the seller can overwrite from their own payout statement; the
// defaults below are a starting point, not Discogs' rate.
//
// Two things this tool exists to make visible that a flat "Discogs takes 9%"
// page misses:
//
// 1. The 9% reaches shipping. A $20 record with $6 shipping pays 9% of $26,
//    and so does the processing fee. Charging postage above what the label
//    costs is taxed like price, not passed through.
// 2. The fixed processing amount is per order, so on a $3 single it is most of
//    the take. `effectiveRate` is the whole cut as a share of what the buyer
//    paid; the fee ladder shows where it flattens out.

/** Selling fee, percent of item + buyer-paid shipping. */
export const SELLING_FEE_RATE = 9;
/** Smallest selling fee on one order, dollars. */
export const SELLING_FEE_MIN = 0.10;
/** Largest selling fee on one order, dollars. */
export const SELLING_FEE_MAX = 150;
/** Default payment processing percent, of item + shipping. Overwritable: not a Discogs-published rate. */
export const DEFAULT_PROCESSING_RATE = 2.9;
/** Default payment processing flat amount per order. Overwritable: not a Discogs-published rate. */
export const DEFAULT_PROCESSING_FIXED = 0.30;

// Every seller-supplied numeric field, in the order the form presents them.
// The page and the share-link encoder both read this rather than keeping
// their own copies.
export const INPUT_IDS = Object.freeze([
  'itemPrice',
  'buyerShipping',
  'labelCost',
  'itemCost',
  'otherCost',
  'targetProfit',
  'processingRate',
  'processingFixed',
]);

// No checkboxes: Discogs has one schedule. Kept so share.mjs stays the same
// shape as the portfolio's other fee calculators.
export const TOGGLE_IDS = Object.freeze([]);

function isBlank(value) {
  return value === '' || value === null || value === undefined || String(value).trim() === '';
}

function number(value, name, { min = 0, allowBlank = false, blankValue = 0 } = {}) {
  if (isBlank(value)) {
    if (allowBlank) return blankValue;
    throw new Error(`${name} is required`);
  }
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  return result;
}

/** Discogs' selling fee on an order total (item + buyer-paid shipping). */
export function sellingFeeOn(combined) {
  if (!(combined > 0)) return 0;
  return Math.min(SELLING_FEE_MAX, Math.max(SELLING_FEE_MIN, combined * (SELLING_FEE_RATE / 100)));
}

/** Discogs' cut of one order: selling fee plus processing. */
export function feeFor({ itemPrice, buyerShipping = 0, processingRate = DEFAULT_PROCESSING_RATE, processingFixed = DEFAULT_PROCESSING_FIXED }) {
  const combined = itemPrice + buyerShipping;
  const sellingFee = sellingFeeOn(combined);
  const processingFee = combined > 0 ? combined * (processingRate / 100) + processingFixed : 0;
  return { sellingFee, processingFee, discogsFee: sellingFee + processingFee };
}

function payoutAt(combined, { labelCost, processingRate, processingFixed }) {
  const { discogsFee } = feeFor({ itemPrice: combined, buyerShipping: 0, processingRate, processingFixed });
  return combined - discogsFee - labelCost;
}

/**
 * The item price that nets exactly `targetPayout` after the fee and a label
 * you paid for, at a fixed buyer-paid shipping amount. Payout rises with the
 * order total at every point (the combined rates are well under 100%), so a
 * bisection finds the single answer even across the $0.10 floor and the $150
 * cap, where a closed form would be wrong on one side of each.
 */
export function priceForTargetPayout(targetPayout, { buyerShipping = 0, labelCost = 0, processingRate = DEFAULT_PROCESSING_RATE, processingFixed = DEFAULT_PROCESSING_FIXED } = {}) {
  if (!Number.isFinite(targetPayout)) return null;
  const opts = { labelCost, processingRate, processingFixed };
  let low = 0;
  let high = 1e7;
  if (payoutAt(high, opts) < targetPayout) return null;
  for (let i = 0; i < 200; i += 1) {
    const mid = (low + high) / 2;
    if (payoutAt(mid, opts) < targetPayout) low = mid;
    else high = mid;
  }
  const price = high - buyerShipping;
  return price >= 0 ? price : null;
}

/**
 * One Discogs sale, priced the way a payout statement lands.
 *
 * @param {object} input
 * @param {number} input.itemPrice        What the buyer paid for the item(s), not shipping.
 * @param {number} [input.buyerShipping]  Shipping the buyer paid on top.
 * @param {number} [input.labelCost]      The postage you paid to ship it.
 * @param {number} [input.itemCost]       What you originally paid for the record(s).
 * @param {number} [input.otherCost]      Mailer, sleeve, tape: packaging on this order.
 * @param {number} [input.targetProfit]   Desired profit; used to solve for an item price.
 * @param {number} [input.processingRate] Payment processing percent. Blank uses the default.
 * @param {number} [input.processingFixed] Payment processing flat amount. Blank uses the default.
 */
export function calculateSale(input) {
  const errors = [];
  const read = (id, label, opts) => {
    try {
      return number(input[id], label, opts);
    } catch (error) {
      errors.push({ id, message: error.message });
      return 0;
    }
  };

  const itemPrice = read('itemPrice', 'Item price');
  const buyerShipping = read('buyerShipping', 'Buyer-paid shipping', { allowBlank: true });
  const labelCost = read('labelCost', 'Postage you paid', { allowBlank: true });
  const itemCost = read('itemCost', 'What you paid for the item', { allowBlank: true });
  const otherCost = read('otherCost', 'Packaging cost', { allowBlank: true });
  const targetProfit = read('targetProfit', 'Target profit', { allowBlank: true });
  const processingRate = read('processingRate', 'Processing rate (%)', { allowBlank: true, blankValue: DEFAULT_PROCESSING_RATE });
  const processingFixed = read('processingFixed', 'Processing flat fee ($)', { allowBlank: true, blankValue: DEFAULT_PROCESSING_FIXED });
  if (processingRate >= 90) errors.push({ id: 'processingRate', message: 'Processing rate (%) must be under 90' });

  if (errors.length) return { ok: false, errors };

  const combined = itemPrice + buyerShipping;
  const { sellingFee, processingFee, discogsFee } = feeFor({ itemPrice, buyerShipping, processingRate, processingFixed });
  const payout = combined - discogsFee - labelCost;
  const profit = payout - itemCost - otherCost;
  const effectiveRate = combined > 0 ? (discogsFee / combined) * 100 : 0;
  const priceForTarget = priceForTargetPayout(targetProfit + itemCost + otherCost, { buyerShipping, labelCost, processingRate, processingFixed });

  const notes = [];
  if (buyerShipping > 0) {
    const onShipping = buyerShipping * ((SELLING_FEE_RATE + processingRate) / 100);
    notes.push(
      `Your $${buyerShipping.toFixed(2)} buyer-paid shipping is inside the fee base: it costs $${onShipping.toFixed(2)} in selling and processing fees on its own. Whether you charge it as shipping or fold it into the item price, Discogs takes the same cut of the total.`,
    );
  }
  if (sellingFee >= SELLING_FEE_MAX) {
    notes.push(`The selling fee is at Discogs' $${SELLING_FEE_MAX} per-order maximum, so every further dollar of this order carries no selling fee (processing still applies).`);
  }
  if (combined > 0 && combined < 5 && processingFixed > 0) {
    notes.push(`On an order this small the flat $${processingFixed.toFixed(2)} processing amount is a large share of the take (${effectiveRate.toFixed(1)}% in all). Combining records into one order spreads it.`);
  }
  if (profit < 0) {
    notes.push('This sale loses money after Discogs’ fees, your postage, what you paid for the item, and packaging.');
  }

  return {
    ok: true,
    errors: [],
    itemPrice,
    buyerShipping,
    labelCost,
    itemCost,
    otherCost,
    targetProfit,
    processingRate,
    processingFixed,
    sellingFee,
    processingFee,
    discogsFee,
    payout,
    profit,
    effectiveRate,
    priceForTarget,
    notes,
  };
}

const LADDER_PRICES = Object.freeze([3, 5, 10, 20, 50, 100, 250, 1000, 2500]);

/**
 * The same shipping and costs at a ladder of item prices, so the seller can
 * see where the take per dollar flattens and where a record stops covering
 * its own fixed fee and postage. The seller's own price is not forced into
 * the ladder; the main result already shows it.
 */
export function feeLadder(input) {
  const base = calculateSale(input);
  if (!base.ok) return { ok: false, errors: base.errors, rows: [] };
  const rows = LADDER_PRICES.map((price) => {
    const sale = calculateSale({ ...input, itemPrice: price });
    return { itemPrice: price, discogsFee: sale.discogsFee, payout: sale.payout, profit: sale.profit, effectiveRate: sale.effectiveRate };
  });
  return { ok: true, errors: [], rows };
}

/**
 * A crate: one order per line, "label, price, shipping, cost" (the label is
 * optional; fields split on commas or tabs, `$` and thousands commas are
 * ignored, a line starting with # is a comment). Missing shipping and cost are
 * 0. Each order is fee'd separately with the same processing rates, because
 * the flat part is per order. Returns every priced row plus totals, so a
 * seller clearing a collection can see which records lose money.
 */
export function calculateBatch(text, settings = {}) {
  const rows = [];
  const problems = [];
  String(text ?? '').split(/\r?\n/).forEach((raw, index) => {
    const line = raw.trim();
    if (!line || line.startsWith('#')) return;
    const cells = line.split(/\t|,(?=(?:[^"]*"[^"]*")*[^"]*$)/).map((cell) => cell.trim().replace(/^"|"$/g, ''));
    const numeric = (cell) => /^\$?-?[\d,]*\.?\d+$/.test(cell.replace(/\s/g, ''));
    let label = '';
    if (cells.length && !numeric(cells[0])) label = cells.shift();
    if (!cells.length || cells.some((cell) => cell !== '' && !numeric(cell))) {
      if (rows.length === 0 && /^(label|title|record|item|price)/i.test(line)) return; // header row
      problems.push({ line: index + 1, message: `Line ${index + 1}: expected "label, price, shipping, cost"` });
      return;
    }
    const [price, shipping = '', cost = ''] = cells.map((cell) => cell.replace(/[$,\s]/g, ''));
    const result = calculateSale({
      processingRate: settings.processingRate,
      processingFixed: settings.processingFixed,
      itemPrice: price,
      buyerShipping: shipping,
      itemCost: cost,
    });
    if (!result.ok) {
      problems.push({ line: index + 1, message: `Line ${index + 1}: ${result.errors[0].message}` });
      return;
    }
    rows.push({ line: index + 1, label: label || `Order ${rows.length + 1}`, ...result });
  });
  const sum = (key) => rows.reduce((total, row) => total + row[key], 0);
  const gross = sum('itemPrice') + sum('buyerShipping');
  const totals = {
    orders: rows.length,
    gross,
    discogsFee: sum('discogsFee'),
    payout: sum('payout'),
    profit: sum('profit'),
    losing: rows.filter((row) => row.profit < 0).length,
    effectiveRate: gross > 0 ? (sum('discogsFee') / gross) * 100 : 0,
  };
  return { rows, problems, totals };
}

share.mjs.text:
// A seller pricing more than one listing has no way to hand a sale's numbers
// to a co-seller or their own other device without retyping every field --
// the "Save" button already shows the browser-local draft was never enough
// by itself. This module keeps the whole form: restored from a link into the
// same draft the page already saves locally between visits.
//
// Nothing here is transmitted. `localStorage` is the visitor's own disk, and
// the link is only ever built in their browser and copied by them. The
// numbers travel in the URL *fragment* (`#...`), never the query string: a
// fragment is not sent in the request line a server logs, nor in a
// `Referer` header a later click would carry, so a shared sale stays off
// the machines it passes through on the way to the recipient.
//
// The field list is imported from `calc.mjs`'s `INPUT_IDS` and `TOGGLE_IDS`
// rather than restated here, so a field added to the arithmetic is
// shareable the moment it exists.

import { INPUT_IDS, TOGGLE_IDS } from './calc.mjs';

export const FIELD_IDS = Object.freeze([...INPUT_IDS]);

function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  return Number.isFinite(result) && result >= 0 ? result : null;
}

export function encodeInputs(input) {
  const params = new URLSearchParams();
  for (const id of FIELD_IDS) {
    const value = usableNumber(input?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  for (const id of TOGGLE_IDS) {
    if (input?.[id] === undefined || input?.[id] === null) continue;
    params.set(id, input[id] ? '1' : '0');
  }
  return params.toString();
}

export function decodeInputs(source) {
  const params = new URLSearchParams(String(source || '').replace(/^[?#]/, ''));
  const result = {};
  for (const id of FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) result[id] = value;
  }
  for (const id of TOGGLE_IDS) {
    if (!params.has(id)) continue;
    const raw = params.get(id);
    // Only the two spellings this module writes. Anything else is a
    // corrupted link, and guessing at it would silently flip the value.
    if (raw === '1' || raw === '0') result[id] = raw === '1';
  }
  return result;
}

/**
 * Turns a decoded link into a value for every field the form owns.
 *
 * Absent is not the same as unchanged: a link that did not carry a field
 * clears it to blank (or off, for the toggle) rather than leaving the
 * recipient's own saved draft sitting in that box, so a plain sale never
 * opens showing a toggle, or an item cost, the sender never
 * sent.
 */
export function formValues(decoded) {
  const values = Object.fromEntries(FIELD_IDS.map(id => [id, decoded?.[id] !== undefined ? String(decoded[id]) : '']));
  for (const id of TOGGLE_IDS) {
    values[id] = decoded?.[id] === true;
  }
  return values;
}

to-where-to-sell.mjs.text:
// Carries this item's numbers into the where-to-sell calculator, with
// Discogs already switched on, so comparing the same item against eBay,
// Etsy, Amazon and a direct sale does not mean retyping price and cost.
//
// This is the reverse of ../where-to-sell-calculator/handoff.mjs, which
// carries a comparison *into* this page. Before this module existed the link
// ran only one way: the where-to-sell calculator could hand its numbers down
// into this page, but a seller who landed here first (from a search for
// "discogs fee calculator", say) and then wanted to check the same item on
// eBay or Etsy had to retype everything. That is the exact failure
// where-to-sell-calculator's own VENTURE.yaml names as its first untested
// hypothesis: the handoff, not the depth of the second tool, decides whether
// the deeper scenarios ever get opened.
//
// Only the numbers every channel shares travel: item price, buyer-paid
// shipping, the postage cost, what the item cost, and the packaging bucket.
// Discogs's own fee -- 9% on item plus shipping, and the processing rate -- is
// not sent, because the receiving page already carries it on its Discogs
// preset (asserted equal to this venture's constants by its
// `channel-parity.test.mjs`).
// Sending it would be restating a rule the other side already holds, which is
// how this repository has twice shipped a stale copy of a rule it should have
// imported.
//
// The wire format is where-to-sell-calculator's own `#c=` shared-link
// payload (see its share.mjs: `decodeComparison`), not this page's own share
// format. `to-where-to-sell.test.mjs` imports that decoder directly so a
// change to its shape fails a test here instead of arriving as a silently
// wrong number there.

const SHARED_FIELDS = ['itemPrice', 'buyerShipping', 'labelCost', 'itemCost', 'otherCost'];
const TARGET_NAME = {
  itemPrice: 'price',
  buyerShipping: 'shippingCharged',
  labelCost: 'shippingCost',
};

function cleanNumber(value) {
  // `Number('')` and `Number(null)` are both 0, so coercing first would turn
  // an untouched field into an explicit zero on arrival -- the silent-wrong-
  // number case this module exists to avoid.
  if (value === null || value === undefined) return null;
  if (typeof value === 'string' && value.trim() === '') return null;
  const number = Number(value);
  return Number.isFinite(number) && number >= 0 ? number : null;
}

/** The `#c=` payload for where-to-sell-calculator's own decoder. */
export function whereToSellPayload(input = {}) {
  const shared = {};
  for (const field of SHARED_FIELDS) {
    const value = cleanNumber(input[field]);
    if (value !== null) shared[TARGET_NAME[field] ?? field] = value;
  }
  // No per-channel rate values: the Discogs preset on the receiving side
  // already carries the 9% fee and processing default, and enabling the channel with
  // no override is exactly what a fresh visit that turns Discogs on already
  // does.
  return { shared, channels: [{ id: 'discogs', enabled: true, values: {} }] };
}

/** A relative link into where-to-sell-calculator, carrying this item. */
export function whereToSellUrl(input = {}) {
  const payload = whereToSellPayload(input);
  const encoded = encodeURIComponent(JSON.stringify(payload));
  return `../where-to-sell-calculator/#c=${encoded}`;
}

usage.mjs.text:
// Records an anonymous, aggregate-only local usage count: the event name and
// the current day, kept in the visitor's own browser. It never stores an
// item price, a cost, or a payout -- a seller's item economics are exactly
// the sort of thing that must not be transmitted anywhere.

const STORAGE_KEY = 'discogs-fee-calculator-usage';

function honorsBrowserSignal() {
  try {
    return globalThis.navigator?.doNotTrack === '1' || globalThis.navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function recordUsage(storage = globalThis.localStorage, optedOut = false, event = 'sale_calculated') {
  if (optedOut || !storage || readOptOut(storage) || honorsBrowserSignal()) return;
  try {
    const today = new Date().toISOString().slice(0, 10);
    const current = JSON.parse(storage.getItem(STORAGE_KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    current.last_day = today;
    storage.setItem(STORAGE_KEY, JSON.stringify(current));
  } catch {
    // A browser refusing site data must not stop the page computing a result.
  }
}

// The opt-out choice is kept in its own key, not in the counters: opting out
// *removes* the counters, so a flag stored inside them would be deleted by
// the very act it records. `recordUsage` above consults it directly as well
// as taking the caller's argument.
export function readOptOut(storage = globalThis.localStorage) {
  try {
    return storage?.getItem(`${STORAGE_KEY}-opt-out`) === '1';
  } catch {
    // A blocked or full store must never be read as consent.
    return false;
  }
}

export function writeOptOut(storage = globalThis.localStorage, optedOut = false) {
  if (!storage) return;
  // Independent writes, counters first: sharing one try means a setItem that
  // throws on a full quota skips the delete entirely, and the visitor gets
  // neither half of what the control promised.
  if (optedOut) {
    try { storage.removeItem(STORAGE_KEY); } catch { /* storage is optional */ }
    try { storage.setItem(`${STORAGE_KEY}-opt-out`, '1'); } catch { /* storage is optional */ }
  } else {
    try { storage.removeItem(`${STORAGE_KEY}-opt-out`); } catch { /* storage is optional */ }
  }
}
